// 显式选择的原Offer不可再走旧岗位受领；旧其它Offer不被新目录误伤。
#include "resident/domains/tasks/personal_acceptances/task_personal_acceptance_services.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
int main(){try{int checks=0;auto need=[&](bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);};TaskPersonalAcceptanceCatalog catalog;catalog.policies.push_back({"policy","letter","sender","accept"});TaskCommand command;command.kind="accept_offer";command.offer_id="letter";auto selected=task_personal_acceptance_original_preview_gate(&catalog,command);need(!selected.ok&&selected.error.original.code=="TaskPersonalAcceptanceRequired","selected original Offer requires unique new acceptance source");need(task_personal_acceptance_original_preview_gate(nullptr,command).ok,"old unselected catalog unchanged");command.offer_id="other";need(task_personal_acceptance_original_preview_gate(&catalog,command).ok,"other original Offer remains original");command.offer_ref=OfferRef{OfferRef::Kind::runtime,"letter"};need(task_personal_acceptance_original_preview_gate(&catalog,command).ok,"runtime ID cannot be mistaken for selected authored Offer");command.offer_ref=OfferRef{OfferRef::Kind::authored,"letter"};need(!task_personal_acceptance_original_preview_gate(&catalog,command).ok,"explicit authored ref has same new source requirement");command.kind="report_offer";need(task_personal_acceptance_original_preview_gate(&catalog,command).ok,"new acceptance selection does not replace report writer");command.source_kind=task_personal_acceptance_source_kind;need(!task_personal_acceptance_original_preview_gate(nullptr,command).ok,"raw command cannot smuggle internal acceptance source kind");std::cout<<checks<<" personal acceptance original-entry cases\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
